(function(){ 'use strict'; function parseImages(node){ var raw=node.getAttribute('data-images')||'[]'; try{var arr=JSON.parse(raw); return Array.isArray(arr)?arr.filter(Boolean):[];}catch(e){return []} } function initRotator(selector,imgSelector){ var wrappers=document.querySelectorAll(selector); wrappers.forEach(function(wrap){ var img=wrap.querySelector(imgSelector||'img'); var images=parseImages(wrap); if(!img||images.length<2) return; var unique=[]; images.forEach(function(src){ if(unique.indexOf(src)===-1) unique.push(src); }); if(unique.length<2) return; var idx=Math.max(0, unique.indexOf(img.getAttribute('src'))); unique.slice(1).forEach(function(src){ var pre=new Image(); pre.decoding='async'; pre.src=src; }); setInterval(function(){ if(document.hidden) return; idx=(idx+1)%unique.length; img.style.opacity='0.35'; setTimeout(function(){ img.src=unique[idx]; img.style.opacity='1'; },160); },3000); img.style.transition='opacity .18s ease'; }); } document.addEventListener('DOMContentLoaded',function(){ initRotator('.category-slide-image-wrapper','img'); initRotator('.product-image','img'); }); })();